#include "batches_runtime.hpp"
#include <rocjpeg/rocjpeg.h>
#include <filesystem>
#include <iterator>
int main(){for(int backend:{0,1}){RocJpegHandle h=nullptr;auto code=rocJpegCreate((RocJpegBackend)backend,0,&h);std::cout<<"create "<<backend<<" "<<code<<std::endl;if(code)continue;for(auto &p:std::filesystem::directory_iterator("nvJPEG/nvJPEG-Decoder/input_images")){std::ifstream f(p.path(),std::ios::binary);std::vector<unsigned char>b((std::istreambuf_iterator<char>(f)),{});RocJpegStreamHandle s;rocJpegStreamCreate(&s);auto parse=rocJpegStreamParse(b.data(),b.size(),s);uint8_t nc=0;RocJpegChromaSubsampling css;uint32_t w[4]={},he[4]={};int info=parse?parse:rocJpegGetImageInfo(h,s,&nc,&css,w,he);int decode=-99;if(!info){migration_batch::Buffer<unsigned char>out(size_t(w[0])*he[0]*3);RocJpegImage image{};image.channel[0]=out.p;image.pitch[0]=w[0]*3;RocJpegDecodeParams params{};params.output_format=ROCJPEG_OUTPUT_RGB;decode=rocJpegDecode(h,s,&params,&image);hipDeviceSynchronize();}std::cout<<"image "<<backend<<" "<<p.path().filename()<<" parse="<<parse<<" info="<<info<<" decode="<<decode<<" size="<<w[0]<<"x"<<he[0]<<std::endl;rocJpegStreamDestroy(s);}rocJpegDestroy(h);}}
